import{_ as a,o as d,c as e,ag as s}from"./chunks/framework.-Wrcbzkw.js";const b=JSON.parse('{"title":"国内云平台概览","description":"","frontmatter":{},"headers":[],"relativePath":"ops/Cloud/国内云/国内云平台概览.md","filePath":"ops/Cloud/国内云/国内云平台概览.md","lastUpdated":1781363231000}'),n={name:"ops/Cloud/国内云/国内云平台概览.md"};function r(l,t,i,o,p,h){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="国内云平台概览" tabindex="-1">国内云平台概览 <a class="header-anchor" href="#国内云平台概览" aria-label="Permalink to &quot;国内云平台概览&quot;">​</a></h1><p>国内云平台适合主要用户位于中国大陆、需要本地化服务支持，或需要满足备案与行业合规要求的业务。</p><h2 id="主流平台" tabindex="-1">主流平台 <a class="header-anchor" href="#主流平台" aria-label="Permalink to &quot;主流平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>云平台</th><th>常见优势</th><th>典型场景</th></tr></thead><tbody><tr><td>阿里云</td><td>产品体系完整，电商与互联网生态成熟</td><td>Web 应用、数据平台、电商业务</td></tr><tr><td>腾讯云</td><td>音视频、游戏、社交生态能力突出</td><td>音视频、游戏、微信生态应用</td></tr><tr><td>华为云</td><td>政企、制造与混合云能力较强</td><td>政企系统、工业互联网、混合云</td></tr><tr><td>火山引擎</td><td>数据分析、内容与增长工具丰富</td><td>内容平台、推荐系统、数据增长</td></tr><tr><td>百度智能云</td><td>AI 与行业解决方案较丰富</td><td>AI 应用、搜索、智能客服</td></tr></tbody></table><h2 id="核心服务类型" tabindex="-1">核心服务类型 <a class="header-anchor" href="#核心服务类型" aria-label="Permalink to &quot;核心服务类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>常见产品类型</th></tr></thead><tbody><tr><td>计算</td><td>云服务器、裸金属、容器服务、Serverless</td></tr><tr><td>网络</td><td>VPC、负载均衡、NAT 网关、CDN、DNS</td></tr><tr><td>存储</td><td>对象存储、云硬盘、文件存储、归档存储</td></tr><tr><td>数据库</td><td>云数据库、缓存、数据仓库、数据湖</td></tr><tr><td>安全</td><td>WAF、DDoS 防护、密钥管理、云防火墙</td></tr><tr><td>运维</td><td>日志服务、监控告警、链路追踪、自动化部署</td></tr></tbody></table><h2 id="选型重点" tabindex="-1">选型重点 <a class="header-anchor" href="#选型重点" aria-label="Permalink to &quot;选型重点&quot;">​</a></h2><ol><li><strong>地域与网络</strong>：确认用户分布、可用区覆盖、跨地域延迟与公网带宽成本。</li><li><strong>备案与合规</strong>：中国大陆公网网站通常需要完成 ICP 备案，并关注等保与数据合规要求。</li><li><strong>产品匹配度</strong>：优先选择团队熟悉且托管服务成熟的平台，减少自行运维成本。</li><li><strong>成本结构</strong>：同时评估计算、存储、流量、快照、日志和跨地域传输费用。</li><li><strong>可迁移性</strong>：使用容器、Terraform 和标准数据库协议，降低平台锁定风险。</li></ol><h2 id="常见基础架构" tabindex="-1">常见基础架构 <a class="header-anchor" href="#常见基础架构" aria-label="Permalink to &quot;常见基础架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求</span></span>
<span class="line"><span>  → CDN / DNS</span></span>
<span class="line"><span>  → WAF / 负载均衡</span></span>
<span class="line"><span>  → 云服务器或容器集群</span></span>
<span class="line"><span>  → 云数据库与缓存</span></span>
<span class="line"><span>  → 对象存储</span></span>
<span class="line"><span>  → 日志、监控与告警</span></span></code></pre></div><h2 id="上线检查" tabindex="-1">上线检查 <a class="header-anchor" href="#上线检查" aria-label="Permalink to &quot;上线检查&quot;">​</a></h2><ul><li>使用多个可用区部署关键服务</li><li>为数据库、对象存储和云硬盘配置备份策略</li><li>限制安全组端口并启用最小权限访问</li><li>配置资源监控、费用告警和异常登录告警</li><li>对域名、证书、备案和到期时间建立台账</li></ul>`,12)])])}const _=a(n,[["render",r]]);export{b as __pageData,_ as default};
